import {tourSteps,demoSteps,interpolatedDemo} from './journey.mjs';
import {learningText} from './optics.mjs';
import {getLanguage} from './i18n.mjs';

export function createGuide(api,optics){
 const text=learningText,launch=document.createElement('dialog');launch.id='learning-launch-dialog';document.body.append(launch);
 const bar=document.createElement('section');bar.id='guide-bar';bar.className='guide-bar';bar.hidden=true;bar.setAttribute('aria-label',text('Geführtes Kameralernen','Guided camera learning'));document.body.append(bar);
 const mobileHost=document.createElement('div');mobileHost.id='mobile-guide-host';mobileHost.hidden=true;document.getElementById('mobile-tabs').after(mobileHost);
 const pointer=document.createElement('div');pointer.className='guide-pointer';pointer.hidden=true;pointer.setAttribute('aria-hidden','true');pointer.textContent='↖';document.body.append(pointer);
 let mode=null,index=0,baseline=null,stepStart=0,elapsed=0,lastTick=0,playing=false,solved=null,exampleShown=false,stamp='',lastFrame='',lastFull=0,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const list=()=>mode==='demo'?demoSteps:tourSteps,current=()=>list()[index];
 const hints={focus:['Tipp: Die Person ist das Motiv bei 4 m, nicht der Hintergrund.','Tip: the person is the subject at 4 m, not the background.'],aperture:['Größere ƒ-Zahl = kleinere Öffnung. „Zeit: Auto“ bleibt dabei aktiv.','Higher f-number = smaller opening. Shutter Auto stays enabled.'],zoom:['Nutze Brennweite links oder ziehe die vordere Objektivgruppe. Die Kamera bleibt stehen.','Use Focal length on the left or drag the front lens group. Leave the camera still.'],motion:['Die markierte Zeit steuert die Länge der Bewegungsspur, nicht das Tempo des Winkens.','The highlighted time controls the motion trail, not the speed of the wave.'],night:['Die Schaltfläche „Automatik ein“ steht unten in „Kamera einstellen“.','Enable auto is at the bottom of Camera setup.'],pupil:['Das Häkchen „Gerundete Lamellen“ steht unter den Optikreglern.','Rounded blades is the checkbox below the optics controls.'],curtains:['Nutze den Zeitregler oder den direkten Knopf „1/1000 s“.','Use the shutter-speed slider or the direct 1/1000 s button.']};
 const entry=document.createElement('button');entry.id='learning-open';entry.className='nav learning-entry';document.querySelector('[data-page="lab"]').after(entry);entry.onclick=()=>{buildLaunch();launch.showModal();};
 const welcome=document.createElement('div');welcome.className='learning-welcome';welcome.innerHTML='';document.getElementById('mobile-panel-controls').prepend(welcome);
 function buildLaunch(){entry.textContent=text('Tour & Demo','Tour & demo');launch.innerHTML=`<form method="dialog"><button class="close" aria-label="${text('Schließen','Close')}">×</button></form><span class="eyebrow">${text('SPIELEN · SEHEN · VERSTEHEN','PLAY · SEE · UNDERSTAND')}</span><h2>${text('Wie möchtest du einsteigen?','How would you like to start?')}</h2><div class="learning-paths"><button data-start="tour"><b>${text('Geführte Tour','Guided tour')}</b><span>${text('Sieben Aha-Momente. Du stellst selbst ein; die App erklärt die Wirkung.','Seven discoveries. You make the adjustments; the app explains the result.')}</span></button><button data-start="demo"><b>${text('Demo ansehen','Watch demo')}</b><span>${text('Eine ruhige, selbstlaufende Vorführung mit Fokusfahrt, Bildausschnitt, Bewegung und Bokeh. Jederzeit pausierbar.','A paced, self-running presentation of focus pulls, framing, motion and bokeh. Pause at any time.')}</span></button><button data-start="optics"><b>${text('Blende verstehen','Understand aperture')}</b><span>${text('Iris öffnen, Lichtwege vergleichen, Lichtpunkte formen.','Open the iris, compare rays and shape light highlights.')}</span></button></div><button data-free class="primary">${text('Frei erkunden','Explore freely')}</button><p class="micro">${text('Tour und Demo verwenden eigene Beispielaufbauten. Beim Beenden kannst du zum vorherigen Stand zurückkehren oder den aktuellen Aufbau behalten. Ohne Ton, Anmeldung oder externe Dienste.','The tour and demo use authored example scenes. On exit, return to your prior setup or keep the current one. No audio, sign-in or external services.')}</p>`;
  welcome.innerHTML=`<span>${text('Neu hier?','New here?')}</span><button data-start="tour">${text('Tour starten','Start tour')}</button><button data-start="demo">${text('Demo ansehen','Watch demo')}</button><button data-free aria-label="${text('Frei erkunden','Explore freely')}">×</button>`;try{welcome.hidden=localStorage.getItem('camera.welcome.v1')==='dismissed';}catch{}
 }
 function dismissWelcome(){welcome.hidden=true;try{localStorage.setItem('camera.welcome.v1','dismissed');}catch{}}
 function clickEntry(e){const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-free')){dismissWelcome();if(launch.open)launch.close();if(mode)stop(true);return;}if(b.dataset.start){dismissWelcome();if(launch.open)launch.close();if(b.dataset.start==='optics')optics.open('aperture');else start(b.dataset.start);}}
 launch.addEventListener('click',clickEntry);welcome.addEventListener('click',clickEntry);
 launch.addEventListener('click',e=>{const r=launch.getBoundingClientRect();if(e.target===launch&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))launch.close();});
 function place(){if(!mode)return;if(optics.isOpen){optics.guide(bar);}else if(document.documentElement.dataset.layout==='mobile'){mobileHost.hidden=false;mobileHost.append(bar);}else{mobileHost.hidden=true;document.body.append(bar);}const top=optics.isOpen?optics.element:document.body;top.append(pointer);}
 function buildBar(){if(!mode)return;const step=current(),done=mode==='tour'&&step.check(api.state());solved=done;bar.dataset.solved=String(done);
  bar.innerHTML=`<div class="guide-heading"><span>${mode==='demo'?text('VORFÜHRUNG','DEMONSTRATION'):text('GEFÜHRTE TOUR','GUIDED TOUR')} · ${index+1} / ${list().length}</span><button data-guide="exit" aria-label="${text('Zum vorherigen Stand zurück','Restore previous setup')}">×</button></div><progress id="guide-progress" max="${list().length}" value="${mode==='demo'?index+Math.min(1,elapsed/current().seconds):index}"></progress><h3>${step.title[getLanguage()==='en'?1:0]}</h3><p class="guide-task">${(mode==='demo'?(step.demoTask||step.task):step.task)[getLanguage()==='en'?1:0]}</p><p class="guide-result" role="status">${mode==='demo'?text('Die App verändert echte Kameraeinstellungen.','The app is changing actual camera settings.'):done?(exampleShown?text('Beispiel eingestellt: ','Example applied: '):'✓ ')+(step.success?.[getLanguage()==='en'?1:0]||''):hints[step.id]?.[getLanguage()==='en'?1:0]||''}</p><details><summary>${text('Was passiert — und warum?','What happens — and why?')}</summary><p>${step.why[getLanguage()==='en'?1:0]}</p></details><div class="guide-actions"><button data-guide="previous" ${index===0?'disabled':''}>← ${text('Zurück','Back')}</button>${mode==='demo'?`<button data-guide="pause" class="primary">${playing?text('Pause','Pause'):text('Fortsetzen','Resume')}</button>`:`<button data-guide="example">${text('Ziel einstellen','Apply target')}</button>`}<button data-guide="next" ${mode==='tour'&&!done?'disabled':''}>${index===list().length-1?text('Abschließen','Finish'):text('Weiter','Next')} →</button></div><div class="guide-links">${mode==='tour'?`<button data-guide="skip">${text('Schritt überspringen','Skip step')}</button>`:''}<button data-guide="restart">${text('Neu starten','Restart')}</button><button data-guide="keep">${text('Mit diesem Aufbau frei erkunden','Explore freely with this setup')}</button></div>`;
  place();api.highlight(step.target,step.view==='optics'?step.detail:null);
 }
 function showStep(i){exampleShown=false;index=Math.max(0,Math.min(list().length-1,i));elapsed=0;stepStart=performance.now();stamp='';lastFrame='';const step=current();api.remember(step.start);api.replace({...step.start,...(reduced?{motion:false}:{})});api.show(step);if(step.view==='optics')optics.open(step.detail,{guided:true});else optics.close();buildBar();}
 function start(which){if(!mode)baseline=api.snapshot();mode=which==='demo'?'demo':'tour';index=0;stamp='';api.suspendLesson();playing=mode==='demo';bar.hidden=false;document.documentElement.dataset.guide=mode;showStep(0);}
 function stop(keep=false){if(!mode)return;const original=baseline;mode=null;playing=false;bar.hidden=true;pointer.hidden=true;mobileHost.hidden=true;delete document.documentElement.dataset.guide;api.highlight(null);optics.close();api.closeAuxiliary?.();document.body.append(bar);if(!keep)api.restore(original);else api.settle?.();baseline=null;}
 function finish(){playing=false;optics.close();api.settle?.();bar.innerHTML=`<div class="guide-heading"><span>${text('DAS WAR DER EINSTIEG','THAT WAS THE INTRODUCTION')}</span><button data-guide="exit">×</button></div><h3>${text('Jetzt gehört die Kamera dir.','Now the camera is yours.')}</h3><p>${text('Weiter experimentieren oder deinen vorherigen Aufbau zurückholen.','Keep experimenting or restore your previous setup.')}</p><div class="guide-actions"><button data-guide="keep" class="primary">${text('Mit diesem Aufbau weiter','Continue with this setup')}</button><button data-guide="exit">${text('Vorherigen Stand wiederherstellen','Restore prior setup')}</button><button data-guide="restart">${text('Neu starten','Restart')}</button></div>`;pointer.hidden=true;api.highlight(null);place();stamp='finished';}
 bar.addEventListener('click',e=>{const action=e.target.closest('[data-guide]')?.dataset.guide;if(!action)return;if(action==='exit')stop();else if(action==='keep')stop(true);else if(action==='restart'){playing=mode==='demo';showStep(0);}else if(action==='pause'){playing=!playing;api.settle?.();lastFrame='';lastTick=performance.now();buildBar();}else if(action==='previous')showStep(index-1);else if(action==='next'||action==='skip'){if(index===list().length-1)finish();else showStep(index+1);}else if(action==='example'){exampleShown=true;api.change(current().end);buildBar();}});
 document.addEventListener('pointerdown',e=>{if(mode==='demo'&&playing&&!e.target.closest('.guide-bar,#learning-launch-dialog')){playing=false;api.settle?.();buildBar();}},true);
 document.addEventListener('keydown',e=>{if(mode&&e.key==='Escape'){e.preventDefault();stop();}},true);
 window.addEventListener('resize',place);document.addEventListener('camera-language-change',()=>{buildLaunch();if(mode&&stamp!=='finished')buildBar();});
 function cursor(){if(!mode||mode!=='demo'||reduced||stamp==='finished'){pointer.hidden=true;return;}const step=current(),target=api.target(step.target,step.view==='optics'?step.detail:null,step),r=target?.element?.getBoundingClientRect();if(!r||!r.width||!r.height){pointer.hidden=true;return;}pointer.hidden=false;pointer.style.left=`${r.left+r.width*(target.fx??.5)}px`;pointer.style.top=`${r.top+r.height*(target.fy??.5)}px`;}
 function tick(now){const dt=lastTick?Math.min(.15,(now-lastTick)/1000):0;lastTick=now;if(mode&&stamp!=='finished'&&!document.hidden){if(mode==='demo'&&playing){elapsed+=dt;const step=current(),progress=Math.min(1,elapsed/step.seconds);{const frame=interpolatedDemo(step,progress,reduced),key=JSON.stringify(frame);if(key!==lastFrame){lastFrame=key;api.frame(frame);if(now-lastFull>350){lastFull=now;api.settle?.();}}}const p=bar.querySelector('progress');if(p)p.value=index+progress;if(progress>=1){if(index<list().length-1)showStep(index+1);else finish();}}else if(mode==='tour'){const done=current().check(api.state());if(done!==solved)buildBar();}cursor();}requestAnimationFrame(tick);}
 buildLaunch();optics.guide(bar);requestAnimationFrame(tick);
 return {start,stop,get active(){return !!mode;},get demoPlaying(){return mode==='demo'&&playing;},update(){if(mode==='tour'&&stamp!=='finished'){const done=current().check(api.state());if(done!==solved)buildBar();}},opticsClosed(){place();},element:bar};
}
